usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Beta.ChatKit.Sessions.New(
		context.TODO(),
		openai.BetaChatKitSessionNewParams{
			Workflow: openai.WorkflowParam{ID: "string", Version: "string", StateVariables: map[string]openai.WorkflowParamStateVariablesValue{"key": "string"}, Tracing: openai.WorkflowTracingParam{Enabled: true}},
			User: "string",
			ExpiresAfter: openai.ExpiresAfterParam{Anchor: "created_at", Seconds: 1},
			RateLimits: openai.RateLimitsParam{MaxRequestsPer1Minute: 1},
			ChatkitConfiguration: openai.ChatkitConfigurationParam{AutomaticThreadTitling: openai.AutomaticThreadTitlingParam{Enabled: true}, FileUpload: openai.FileUploadParam{Enabled: true, MaxFileSize: 1, MaxFiles: 1}, History: openai.HistoryParam{Enabled: true, RecentThreads: 1}},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
